        /* sdd-asis-lifecycle:begin ipt_searchWord_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_boardCheck(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05200.ipt_searchWord_onkeyup' }); }
};

/**
 * @event
 * @name scwin.btn_search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
