*/
scwin.btn_search_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05200.btn_search_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_resultList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_resultList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.open_corpView === 'function') { scwin.open_corpView(r["isurCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.open_corpView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.open_corpView'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/corp/corpList.do?method=corpInfoList",
        ref: "dma_searchReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf05200.tx_fn_search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_goPage
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goPage = async function () {
    const sbmOptions = {
        id: "tx_fn_goPage",
        method: "post",
        action: "/corp/corpList.do?method=corpInfoList",
        ref: "dma_goPageReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf05200.tx_fn_goPage" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_resultList_fmt_isurCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_resultList_fmt_isurCd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "isur_chk") ?? '') : '');
        if (v !== '#') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "isurCd") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "isurCd") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.isurCd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) == 0) {
        await $c.win.alert("발행기관명(코드)를 입력하세요");
        $c.util.getComponent("ipt_searchWord").focus();
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord").getValue() || ''));
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) <= 2) {
        await $c.win.alert("발행기관명(코드)를 확인하세요");
        $c.util.getComponent("ipt_searchWord").focus();
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord").getValue() || ''));
        return;
    }
    const frm = (document.JLDINF05200 || { elements: [] });
    frm.action = "/corp/corpList.do?method=corpInfoList";
    frm.target = "_top";
    blockLoading();
    await scwin.tx_fn_search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goPage
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goPage = async function () {
    /* sdd-asis-lifecycle:begin fn_goPage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_searchWord').getValue() == null ? '' : String($c.util.getComponent('ipt_searchWord').getValue())) === '') {
        $c.util.getComponent('ipt_searchWord').setValue($("paramSearchWord").val());
    }
    const frm = (document.JLDINF05200 || { elements: [] });
    frm.action = "/corp/corpList.do?method=corpInfoList";
    blockLoading();
    await scwin.tx_fn_goPage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.open_corpView
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_isurCd
 * @returns
 * @hidden N
*/
scwin.open_corpView = function (ipt_isurCd) {
    /* sdd-asis-lifecycle:begin open_corpView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formName = (document.popupForm || { elements: [] });
    $c.util.getComponent("dma_searchReq").set("isurCd", ipt_isurCd);
    fn_popupCorpView(formName, ipt_isurCd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.open_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_isurCd
 * @returns
 * @hidden N
*/
scwin.open_modify = function (ipt_isurCd) {
    /* sdd-asis-lifecycle:begin open_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_isurCd').setValue(ipt_isurCd);
    const formName = (document.popupForm || { elements: [] });
    fn_popupCorpUpdReq(formName, $c.util.getComponent('ipt_isurCd').getValue());
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.open_notCorpUpdMsg
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.open_notCorpUpdMsg = async function () {
    /* sdd-asis-lifecycle:begin open_notCorpUpdMsg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert("상장법인은 법인정보를 변경할 수 없습니다.\n법인정보 변경은 해당 상장사 공시 담당자에게 문의하시기 바랍니다.\n문의전화 : 02-3774-8684");
    return;
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_83_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_83_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_83.page' }); } scwin.goPage(); };
